import React, { useState } from 'react';
import Chatbot from './components/Chatbot';
import CourseCard from './components/CourseCard';
import RoadmapChart from './components/RoadmapChart'; // ⬅️ new import
import './App.css';

function App() {
  const [recommendedCourses, setRecommendedCourses] = useState([]);
  const [roadmapData, setRoadmapData] = useState([]); // ⬅️ roadmap state

  const handleResponse = (data) => {
    if (data.courses) {
      setRecommendedCourses(data.courses);

      // 🗺️ Generate better roadmap: categorize skills
      const roadmap = data.courses.map((course) => {
        const title = course.title.toLowerCase();
        let skill = 'General Skills';

        if (title.includes('machine')) skill = 'Machine Learning';
        else if (title.includes('data')) skill = 'Data Analysis';
        else if (title.includes('regression') || title.includes('statistics')) skill = 'Statistics';
        else if (title.includes('web')) skill = 'Web Development';
        else if (title.includes('ai')) skill = 'Artificial Intelligence';
        else if (title.includes('visualization')) skill = 'Data Visualization';

        return {
          career: 'Aligned to career goal',  // You can replace this with user goal if passed
          skill,
          course: course.title,
        };
      });

      setRoadmapData(roadmap);
    } else {
      setRecommendedCourses([]);
      setRoadmapData([]);
    }
  };

  return (
    <div className="main-wrapper">
      <header className="app-header">
        <h1>🎓 Smart Course Selector</h1>
      </header>
      <div className="app-container">
        <div className="chat-section">
          <Chatbot onResponse={handleResponse} />
        </div>
        <div className="recommendation-section">
          <h2 className="recommendation-title">📚 Recommended Courses</h2>
          {recommendedCourses.length === 0 ? (
            <p className="no-recommendation-text">Please complete the chatbot from the left to get recommendation</p>
          ) : (
            recommendedCourses.map((course, index) => (
              <CourseCard key={index} course={course} />
            ))
          )}

          {/* 🧭 Roadmap section below recommendations */}
          {roadmapData.length > 0 && (
            <>
              <h2 className="recommendation-title">🗺️ Learning Roadmap</h2>
              <RoadmapChart roadmapData={roadmapData} />
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
